MINIMAL_HTML = '<!doctype html>\n<html lang="en" data-app="notifications">\n<head>\n<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="dark light">\n<title>Notifications</title>\n<script src="minimal-boot.js"></script><link rel="stylesheet" href="minimal-kit.css"><link rel="stylesheet" href="minimal.css">\n<script src="/wizard-os-home/core/app-client.js"></script><script src="layout.js"></script><script defer src="minimal.js"></script>\n</head>\n<body><div class="wz-app">\n<header class="wz-head"><h1>Notifications</h1></header>\n<main class="wz-scroll" id="scroll" tabindex="-1">\n<section id="overview" aria-label="Notification subjects"><ul class="wz-list" id="list"></ul><p class="wz-empty" id="empty" hidden>No unread notifications</p></section>\n<section id="detail" aria-labelledby="subject" hidden><button type="button" id="back">← Back</button><h2 id="subject" tabindex="-1"></h2><p id="meta"></p><div id="body"></div><div class="actions" id="actions"></div><p id="reply-note">Opens an unsent draft with this notification as quoted reference data. Review it in Chats; nothing is sent automatically.</p></section>\n</main>\n<p class="wz-status" id="status" role="status" aria-live="polite"></p>\n<footer id="toolbar"><nav aria-label="Notification filter" id="filters"><button type="button" data-filter="unread" aria-pressed="true">Unread</button><button type="button" data-filter="all" aria-pressed="false">All</button></nav><button type="button" id="more" aria-expanded="false" aria-controls="options">More</button><div id="options" hidden><button type="button" data-filter="flagged">Flagged</button><button type="button" data-filter="archive">Archive</button><button type="button" id="allread">Mark all read</button><button type="button" id="refresh">Refresh</button></div></footer>\n</div></body></html>\n'
MINIMAL_ASSETS = {'minimal.js': ('text/javascript', "'use strict';\n(() => {\n  const el = id => document.getElementById(id);\n  let filter = 'unread', items = [], selected = null, generation = 0, busy = false;\n  const titleOf = it => String(it.title || String(it.message || '').split('\\n')[0] || 'Untitled notification');\n  const say = text => { el('status').textContent = text || ''; };\n  function node(tag, text, cls) { const n = document.createElement(tag); if (text != null) n.textContent = String(text); if (cls) n.className = cls; return n; }\n  async function api(path, data) {\n    const response = await fetch('api/' + path, data ? {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(data)} : {cache: 'no-store'});\n    const result = await response.json();\n    if (!response.ok) throw new Error(result.error || 'Notifications are not reachable. Try Refresh.');\n    return result;\n  }\n  function visible() { return filter === 'unread' ? items.filter(it => !it.read) : items; }\n  function paint() {\n    el('list').replaceChildren(...visible().map(it => {\n      const li = node('li'), button = node('button', null, 'subject-row' + (it.read ? '' : ' unread'));\n      button.type = 'button'; button.dataset.id = it.id;\n      button.setAttribute('aria-label', titleOf(it) + (it.read ? '' : ', unread'));\n      const dot = node('span', '', 'dot'); dot.setAttribute('aria-hidden', 'true');\n      button.append(dot, node('span', titleOf(it), 'title')); li.append(button); return li;\n    }));\n    el('empty').hidden = visible().length !== 0;\n    el('empty').textContent = filter === 'unread' ? 'No unread notifications' : filter === 'flagged' ? 'No flagged notifications' : filter === 'archive' ? 'No archived notifications' : 'No notifications';\n    document.querySelectorAll('[data-filter]').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.filter === filter)));\n    el('overview').hidden = !!selected; el('detail').hidden = !selected;\n    if (selected) paintDetail();\n  }\n  function action(label, handler, disabled = false) {\n    const b = node('button', label); b.type = 'button'; b.disabled = disabled || busy; b.onclick = handler; return b;\n  }\n  function paintDetail() {\n    const it = selected;\n    el('subject').textContent = titleOf(it);\n    const date = new Date(Number(it.time) * 1000);\n    el('meta').textContent = [Number.isNaN(date.getTime()) ? '' : date.toLocaleString(), it.read ? 'Read' : 'Unread', it.flag ? 'Flagged' : '', it.archived ? 'Archived' : ''].filter(Boolean).join(' · ');\n    el('body').textContent = String(it.message || '');\n    const a = el('actions'); a.replaceChildren();\n    const reply = action('Start chat', () => {\n      try {\n        const receipt = window.WizardApp.nav.openContextDraft({id: String(it.id), title: titleOf(it), message: String(it.message || '')});\n        if (receipt?.kind !== 'unsent-draft' || receipt.sent !== false) throw new Error('Could not confirm an unsent draft.');\n        say('Draft opened in Chats. Nothing sent.');\n      } catch (error) { say(error.message || 'Could not open Chats.'); }\n    }); reply.setAttribute('aria-describedby', 'reply-note'); a.append(reply);\n    a.append(action(it.read ? 'Mark unread' : 'Mark read', () => mark([it.id], {read: !it.read})));\n    a.append(action(it.flag ? 'Unflag' : 'Flag', () => mark([it.id], {flag: !it.flag})));\n    a.append(action(it.archived ? 'Move to inbox' : 'Archive', () => mark([it.id], {archived: !it.archived})));\n    try {\n      const url = new URL(it.link);\n      if (url.protocol === 'https:') { const link = node('a', 'Open link'); link.href = url.href; link.target = '_blank'; link.rel = 'noopener noreferrer'; a.append(link); }\n    } catch (_) {}\n  }\n  async function load() {\n    const version = ++generation;\n    const view = filter === 'unread' ? 'inbox' : filter;\n    try {\n      const result = await api('items?view=' + encodeURIComponent(view) + '&limit=500');\n      if (version !== generation) return;\n      if (!Array.isArray(result.items)) throw new Error('Notifications returned an invalid list.');\n      items = result.items;\n      if (selected) selected = items.find(it => it.id === selected.id) || selected;\n      paint(); say('');\n      const c = result.counts || {};\n      if (parent !== window) parent.postMessage({type: 'wizard:notifications:count', unread: Number(c.unread) || 0, needs: Number(c.needs) || 0}, location.origin);\n    } catch (error) { if (version === generation) say(error.message); }\n  }\n  async function mark(ids, marks) {\n    if (busy || !ids.length) return;\n    busy = true; if (selected) paintDetail();\n    try {\n      await api('mark', {ids, ...marks});\n      if (selected && ids.includes(selected.id)) selected = {...selected, ...marks};\n      await load();\n    } catch (error) { say(error.message); }\n    finally { busy = false; if (selected) paintDetail(); }\n  }\n  function closeDetail() {\n    if (!selected) return false;\n    const id = selected.id; selected = null; paint();\n    const row = [...document.querySelectorAll('.subject-row')].find(b => b.dataset.id === id); (row || el('scroll')).focus(); return true;\n  }\n  el('list').onclick = e => {\n    const b = e.target.closest('[data-id]'); if (!b) return;\n    selected = items.find(it => it.id === b.dataset.id); if (!selected) return;\n    paint(); el('scroll').scrollTop = 0; el('subject').focus();\n  };\n  document.querySelectorAll('[data-filter]').forEach(b => b.onclick = () => {\n    filter = b.dataset.filter; selected = null; el('options').hidden = true; el('more').setAttribute('aria-expanded', 'false'); el('scroll').scrollTop = 0;\n    // Clear old rows while the new filter loads, never label stale data “All”.\n    items = []; paint(); load();\n  });\n  el('back').onclick = closeDetail;\n  el('more').onclick = () => { el('options').hidden = !el('options').hidden; el('more').setAttribute('aria-expanded', String(!el('options').hidden)); };\n  el('refresh').onclick = load;\n  el('allread').onclick = () => {\n    const ids = visible().filter(it => !it.read).map(it => it.id);\n    if (ids.length && confirm('Mark the ' + ids.length + ' displayed notifications as read?')) mark(ids, {read: true});\n  };\n  window.__wizardCloseOverlay = () => {\n    if (!el('options').hidden) { el('options').hidden = true; el('more').setAttribute('aria-expanded', 'false'); el('more').focus(); return true; }\n    return closeDetail();\n  };\n  document.addEventListener('keydown', e => { if (e.key === 'Escape') window.__wizardCloseOverlay(); });\n  window.WizardApp?.ready({name: 'Notifications'});\n  window.WizardApp?.back?.register?.({canGoBack: () => !!selected || !el('options').hidden, back: () => window.__wizardCloseOverlay()});\n  document.addEventListener('visibilitychange', () => { if (!document.hidden) load(); });\n  setInterval(() => { if (!document.hidden && !busy) load(); }, 60000);\n  load();\n})();\n"), 'minimal.css': ('text/css', '.wz-app { max-width: 760px; width: 100%; }\n.wz-scroll { padding: 8px 18px; overscroll-behavior: contain; }\n[hidden] { display: none !important; }\nbutton, a { -webkit-tap-highlight-color: transparent; }\nbutton { min-height: 44px; border: 0; background: none; color: inherit; font: inherit; cursor: pointer; }\nbutton:disabled { cursor: not-allowed; color: var(--ink-3); }\n:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }\n.subject-row { display: flex; align-items: center; gap: 10px; width: 100%; min-height: 56px; text-align: left; border-bottom: 1px solid var(--line); padding: 10px 2px; }\n.subject-row:hover { background: var(--fill); }\n.subject-row .title { min-width: 0; flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-weight: 450; }\n.subject-row.unread .title { font-weight: 650; }\n.dot { flex: 0 0 6px; width: 6px; height: 6px; border-radius: 50%; background: transparent; }\n.unread .dot { background: var(--accent); }\n#toolbar { flex: none; position: relative; display: flex; align-items: center; justify-content: center; gap: 12px; padding: 12px 18px max(44px, env(safe-area-inset-bottom)); border-top: 1px solid var(--line); }\n#filters { display: flex; border-radius: 99px; background: var(--fill); padding: 3px; }\n#filters button { min-width: 90px; padding: 0 18px; border-radius: 99px; color: var(--ink-2); }\n#filters button[aria-pressed="true"] { background: var(--fill-2); color: var(--ink); font-weight: 650; }\n#more { color: var(--ink-2); padding: 0 10px; }\n#options { position: absolute; right: 18px; bottom: calc(100% + 4px); min-width: 170px; padding: 8px; border: 1px solid var(--line-2); border-radius: 16px; background: var(--wz-surface-raised, var(--canvas)); box-shadow: 0 10px 36px var(--line); z-index: 3; }\n#options button { display: block; width: 100%; padding: 0 12px; text-align: left; border-radius: 8px; }\n#options button:hover { background: var(--fill); }\n#back { color: var(--ink-2); padding: 0 4px; }\n#subject { font-size: 22px; line-height: 1.3; margin: 16px 0 8px; overflow-wrap: anywhere; }\n#meta, #reply-note { font-size: 13px; color: var(--ink-2); }\n#body { margin: 24px 0; white-space: pre-wrap; overflow-wrap: anywhere; line-height: 1.65; }\n.actions { display: flex; flex-wrap: wrap; gap: 8px; margin: 20px 0 10px; }\n.actions button, .actions a { border-radius: 99px; padding: 10px 16px; background: var(--fill); text-decoration: none; display: inline-flex; align-items: center; color: var(--ink); }\n.actions button:disabled { color: var(--ink-3); }\n#reply-note { max-width: 52ch; line-height: 1.5; }\n.wz-status { color: var(--ink-2); padding: 0 18px; }\n.wz-status:empty { padding: 0; margin: 0; }\n@media (min-width: 768px) { #toolbar { order: -1; justify-content: flex-start; border-top: 0; border-bottom: 1px solid var(--line); } #options { top: calc(100% + 4px); bottom: auto; left: 18px; right: auto; } .wz-head { order: -2; } }\n'), 'minimal-kit.css': ('text/css', '/* Wizard UI kit for generated apps (builder template, MVP).\n *\n * Rule 1: a hosted app paints NO canvas. In a window or fullscreen the shell\'s window glass is the\n *         canvas, exactly as it is for Chats. Only a standalone tab paints the skin\'s background.\n * Rule 2: speak Chats\' visual language: system UI type at the shell\'s sizes, ink / ink-2 / ink-3\n *         hierarchy, hairline separators, faint tinted fills instead of opaque cards, pill inputs,\n *         a round accent action. Every value derives from the appearance v1 roles (--wz-*), so all\n *         the five accepted skins and future shell-approved skins flow through without per-app colour work.\n * Rule 3: layout and content stay the app\'s own. Use these classes; add app styles in styles.css.\n *\n * Values mirror web/core/chats.css and core/base.css in Wizard UX (ch-row, ch-sec-h, ch-compose). */\n\n:root {\n  --ink: var(--wz-text, #f3efff);\n  --ink-2: var(--wz-text-secondary, #b9b0d8);\n  --ink-3: var(--wz-text-muted, #a59abf);\n  --line-2: var(--wz-border, rgba(205, 190, 255, .24));\n  --line: color-mix(in srgb, var(--line-2) 55%, transparent);\n  --fill: color-mix(in srgb, var(--ink) 6%, transparent);\n  --fill-2: color-mix(in srgb, var(--ink) 10%, transparent);\n  --accent: var(--wz-accent, #b99bff);\n  --on-accent: var(--wz-on-accent, #160b32);\n  --accent-soft: var(--wz-accent-soft, rgba(143, 99, 255, .16));\n  --canvas: var(--wz-canvas, #05030c);\n  --danger: #ff8f8f;\n  --r: 14px;          /* rows, panels */\n  --r-tile: 12px;     /* 36px tiles, search */\n  --r-pill: 20px;     /* composer input */\n  --ease: cubic-bezier(.2, .9, .25, 1);\n  --font: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", sans-serif;\n  color-scheme: dark;\n}\nhtml[data-color-scheme="light"] { color-scheme: light; --danger: #b42318; }\n/* Skin shape. The protocol carries colour only today; these two skins also change shape in the shell. */\nhtml[data-skin="signal"] { --r: 2px; --r-tile: 2px; --r-pill: 2px; }\nhtml[data-skin="signal"] .wz-sec-h { font-family: ui-monospace, "SF Mono", Menlo, monospace; letter-spacing: .08em; }\n\n*, *::before, *::after { box-sizing: border-box; }\nhtml, body { height: 100%; margin: 0; }\nhtml { -webkit-text-size-adjust: 100%; -webkit-tap-highlight-color: transparent; }\nbody { font: 15px/1.4 var(--font); color: var(--ink); background: transparent; -webkit-font-smoothing: antialiased; overscroll-behavior: none; }\nhtml[data-presentation="standalone"]:not(.wz-hosted) body { background: var(--canvas); }\nbutton, input, textarea, select { font: inherit; color: inherit; }\nbutton { cursor: pointer; border: 0; background: none; padding: 0; }\n:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }\n.wz-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }\n\n/* ---------- frame: head / scroll / composer, like a Chats thread ---------- */\n.wz-app { display: flex; flex-direction: column; height: 100%; max-width: 640px; margin: 0 auto; }\n.wz-head { flex: none; display: flex; align-items: flex-end; gap: 12px; padding: calc(var(--wos-cutout, 0px) + 18px) 18px 6px; }\n.wz-head h1 { margin: 0; font-size: 26px; line-height: 1.15; font-weight: 750; letter-spacing: -.02em; }\n.wz-head p { margin: 0 0 3px auto; font-size: 13px; color: var(--ink-3); }\n/* In a window the shell\'s title bar already names the app. */\nhtml[data-presentation="window"] .wz-head { display: none; }\n.wz-scroll { flex: 1; min-height: 0; overflow-y: auto; padding: 4px 10px 12px; scrollbar-width: none; }\n.wz-scroll::-webkit-scrollbar { display: none; }\n\n/* ---------- section label: .ch-sec-h ---------- */\n.wz-sec + .wz-sec { border-top: 1px solid var(--line); }\n.wz-sec-h { display: flex; align-items: center; gap: 10px; margin: 0; padding: 12px 8px 8px; font-size: 11.5px; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; color: var(--ink-2); }\n.wz-sec-h small { font-size: 11.5px; font-weight: 800; letter-spacing: .05em; color: var(--ink-3); }\n.wz-count { margin-left: auto; padding: 1px 8px; border-radius: 99px; font-size: 10.5px; letter-spacing: .04em; color: var(--ink-2); background: var(--fill); }\n.wz-count.all { color: var(--on-accent); background: var(--accent); }\n\n/* ---------- rows: .ch-row ---------- */\n.wz-list { list-style: none; margin: 0; padding: 0; }\n.wz-row { display: flex; align-items: center; gap: 12px; width: 100%; min-height: 52px; padding: 8px; border-radius: var(--r); text-align: left; transition: background 140ms; }\n.wz-row:active { background: var(--fill); }\n@media (hover: hover) { .wz-row:hover { background: var(--fill); } }\n.wz-row .wz-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }\n.wz-row .wz-main b { font-size: 15px; font-weight: 600; color: var(--ink); overflow-wrap: anywhere; }\n.wz-row .wz-main small { font-size: 13px; color: var(--ink-3); }\n.wz-tile { flex: none; width: 36px; height: 36px; border-radius: var(--r-tile); display: grid; place-items: center; font-size: 18px; background: var(--fill); }\n\n/* round check, 26px inside a 36px tile-sized slot (the whole row is the 44px+ target) */\n.wz-check { flex: none; width: 36px; height: 36px; display: grid; place-items: center; }\n.wz-check i { width: 26px; height: 26px; border-radius: 50%; border: 2px solid var(--line-2); display: grid; place-items: center; transition: background 160ms var(--ease), border-color 160ms, transform 220ms var(--ease); }\n.wz-check svg { width: 14px; height: 14px; fill: none; stroke: var(--on-accent); stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; opacity: 0; transition: opacity 120ms; }\nhtml[data-skin="signal"] .wz-check i { border-radius: 2px; }\n[aria-pressed="true"] .wz-check i { background: var(--accent); border-color: var(--accent); transform: scale(1.04); }\n[aria-pressed="true"] .wz-check svg { opacity: 1; }\n[aria-pressed="true"] .wz-main b { color: var(--ink-2); }\n.wz-row:disabled { opacity: .6; cursor: progress; }\n\n/* ---------- empty state ---------- */\n.wz-empty { padding: 44px 24px 24px; text-align: center; color: var(--ink-3); }\n.wz-empty .wz-tile { margin: 0 auto 14px; width: 52px; height: 52px; border-radius: 18px; font-size: 24px; color: var(--accent); }\n.wz-empty strong { display: block; margin-bottom: 4px; font-size: 16px; font-weight: 700; color: var(--ink); }\n.wz-empty p { margin: 0 auto; max-width: 30ch; font-size: 14px; line-height: 1.4; }\n\n/* ---------- composer: .ch-compose ---------- */\n.wz-compose { flex: none; display: flex; align-items: center; gap: 8px; padding: 8px 10px calc(10px + env(safe-area-inset-bottom, 0px)); border-top: 1px solid var(--line); }\n.wz-input { flex: 1; min-width: 0; height: 42px; padding: 0 16px; border-radius: var(--r-pill); border: 1px solid var(--line-2); outline: 0; background: var(--fill); color: var(--ink); font-size: 15px; }\n.wz-input::placeholder { color: var(--ink-3); }\n.wz-input:focus { border-color: color-mix(in srgb, var(--accent) 60%, transparent); }\n.wz-send { flex: none; width: 42px; height: 42px; border-radius: 50%; display: grid; place-items: center; background: var(--accent); color: var(--on-accent); transition: opacity 140ms, transform 140ms; }\nhtml[data-skin="signal"] .wz-send { border-radius: 2px; }\n.wz-send svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2.6; stroke-linecap: round; }\n.wz-send:disabled { opacity: .4; cursor: default; }\n.wz-send:not(:disabled):active { transform: scale(.94); }\n\n/* ---------- status: errors are visible, confirmations are for screen readers ---------- */\n.wz-status { flex: none; margin: 0; padding: 0 18px 6px; min-height: 0; font-size: 13px; color: var(--danger); }\n.wz-status:empty { padding: 0; }\n.wz-status.note { color: var(--ink-2); text-align: center; }\n\n/* Staging hosts label the page once; a hosted app never repeats that badge. */\nhtml.wz-hosted #wiz-staging-tag { display: none !important; }\n\n@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none !important; animation: none !important; } }\n'), 'minimal-boot.js': ('text/javascript', "/* Runs before first paint: a hosted app never flashes a standalone canvas while the shell's\n * appearance message is on its way. */\ntry { if (window.parent !== window) document.documentElement.classList.add('wz-hosted'); }\ncatch (e) { document.documentElement.classList.add('wz-hosted'); }\n"), 'layout.js': ('text/javascript', "(() => {\n const ours = new Set(['obsidian','obsidian-light','landscapes']);\n const minimal = new URL(location.href).searchParams.get('layout') === 'minimal';\n window.WizardApp?.theme.onChange(theme => {\n   const skin = theme?.skin?.id || theme?.skin || document.documentElement.dataset.skin;\n   if (!skin) return;\n   const wanted = ours.has(skin);\n   if (wanted !== minimal) { const url = new URL(location.href); if (wanted) url.searchParams.set('layout','minimal'); else url.searchParams.delete('layout'); location.replace(url.href); }\n });\n})();")}
